    const update = (key: Key, value: Value) => {
        cache.set(key, value)
        cacheSize++

        if (cacheSize > maxCacheSize) {
            cacheSize = 0
            previousCache = cache
            cache = new Map()
        }
    }

    return {
        get(key) {
            let value = cache.get(key)

            if (value !== undefined) {
                return value
            }
            if ((value = previousCache.get(key)) !== undefined) {
                update(key, value)
                return value
            }
        },
        set(key, value) {
            if (cache.has(key)) {
                cache.set(key, value)
            } else {
                update(key, value)
            }
