import { EnvConfig, Language, PrismGrammar, PrismLib } from "../types"
import normalizeTokens from "../utils/normalizeTokens"
import { useMemo } from "react"

type Options = {
  prism: PrismLib
  code: string
  grammar?: PrismGrammar
  language: Language
}

export const useTokenize = ({ prism, code, grammar, language }: Options) => {
  return useMemo(() => {
    if (grammar == null) return normalizeTokens([code])

    const prismConfig: EnvConfig = {
      code,
      grammar,
      language,
      tokens: [],
    }

    prism.hooks.run("before-tokenize", prismConfig)
    prismConfig.tokens = prism.tokenize(code, grammar)
    prism.hooks.run("after-tokenize", prismConfig)
    return normalizeTokens(prismConfig.tokens)
  }, [
    code,
    grammar,
    language,
    // prism is a stable import
    prism,
  ])
}
import type { Language, StyleObj, PrismTheme } from "../types"
export type ThemeDict = {
  root: StyleObj
  plain: StyleObj
  [type: string]: StyleObj
}

const themeToDict = (theme: PrismTheme, language: Language): ThemeDict => {
  const { plain } = theme
  const themeDict = theme.styles.reduce<ThemeDict>((acc, themeEntry) => {
    const { languages, style } = themeEntry

    if (languages && !languages.includes(language)) {
      return acc
    }

    themeEntry.types.forEach(type => {
      const accStyle: StyleObj = { ...acc[type], ...style }
      acc[type] = accStyle
    })
    return acc
  }, {} as ThemeDict)

  themeDict.root = plain as StyleObj
  themeDict.plain = { ...plain, backgroundColor: undefined } as StyleObj
  return themeDict
}

